const input = $items("Prepare Assistant Context")[0]?.json || {};
const ai = $items("OpenRouter AI Assistant")[0]?.json || {};

const answer =
  ai.choices?.[0]?.message?.content ||
  ai.body?.choices?.[0]?.message?.content ||
  "AI asistan şu anda yanıt oluşturamadı. Lütfen biraz sonra tekrar deneyin.";

return [
  {
    json: {
      ok: true,
      answer,
      mode: "n8n_openrouter",
      model: ai.model || "openrouter/free",
      userName: input.userName,
      role: input.role,
    },
  },
];
